 "client_cluster": [
  "locale:429032 [quest_dialog | Camp Chatty | Camp Troubles] 'Lately, a lot of campers have been scared off by something. I wish I knew what it was!'",
  "locale:429033 [quest_dialog | Camp Chatty | Meet and Greet] 'If you ask me, a camp in the forest is the perfect spot to bond with wildlife. <BR><BR>How about it? Want to make some new friends with the animals nearby?'",
  "locale:429035 [npc_dialog | Camp Chatty | -] \"I have an awesome tower defense game prepared at this table. <BR><BR>Don't scoff! These lessons you learn from games can be important in real life! You want to \"",
  "locale:429037 [npc_dialog | Camp Chatty | -] \"I used to be on the track and field team in school. Now I'm here to share my passion for running with everyone!\"",
  "locale:429046 [quest_objective | Camp Chatty | Meet and Greet] 'Meet the camp counselors of Camp Chatty.'",
  "locale:429047 [quest_objective | Camp Chatty | Meet and Greet] 'Speak to Counselor Kaela'",
  "locale:429049 [quest_objective | Camp Chatty | Meet and Greet] 'Speak to Counselor Tyra'",
  "locale:429051 [quest_objective | Camp Chatty | Meet and Greet] 'Speak to Counselor Jake'",
  "locale:429053 [quest_objective | Camp Chatty | Meet and Greet] 'Speak to Counselor Edmond'",
  "locale:429055 [quest_dialog | Camp Chatty | Meet and Greet] \"Did you already meet my camp counselors yet? They're somewhere around Camp Chatty.\"",
  "locale:429057 [other | - | Bigfoot is Robbie | FLAG dev_note: internal proc note] 'Bigfoot is Robbie Proc'",
  "locale:429058 [other | - | Robbie | FLAG dev_note: internal proc note] 'on death proc - Spawns Robbie'",
  "locale:429059 [quest_objective | Camp Chatty | Camp Troubles] 'Return to Chatty'",
  "locale:429061 [quest_dialog | Camp Chatty | Camp Troubles] \"*sigh* I know people are here for fun and games, but we've been having some troubles.<BR><BR>Campers are reporting sightings of a big scary monster they call, B\"",
  "locale:429062 [quest_title | Camp Chatty | Camp Troubles] 'Camp Troubles'",
  "locale:429063 [quest_dialog | Camp Chatty | Camp Troubles] 'Bigfoot has been scaring off many campers. However, it is very elusive, and none of the counselors have been able to find it. See if you can find its lair.'",
  "locale:429064 [quest_objective | Camp Chatty | Camp Troubles] 'The foot prints lead to a copse of trees. That must be where Bigfoot hides out!'",
  "locale:429066 [quest_objective | - | Bigfoot's Lair] \"Help the camp counselors find Bigfoot's lair.\"",
  "locale:429067 [quest_title | - | Find Bigfoot's Lair] \"Find Bigfoot's Lair\"",
  "locale:429069 [quest_objective | - | Counselor Edmond] 'Return to Counselor Edmond'",
  "locale:429071 [quest_dialog | - | Find Bigfoot's Lair] 'Did you find any clues yet? I wonder where this &quot;Bigfoot&quot; could be hiding.<BR><BR>We should find it before it scares off more campers.<BR>'",
  "locale:429073 [quest_dialog | - | Bigfoot's Lair] \"You're welcome to join us if you like. We'll go on ahead. <BR><BR>Once you're equipped, <font color='#D9781A'>join us at Bigfoot's lair</font>.\"",
  "locale:429074 [quest_title | - | Confronting Bigfoot] 'Confronting Bigfoot'",
  "locale:429075 [quest_objective | - | Confronting Bigfoot] \"Edmond and the other camp counselors can't seem to make peace with Bigfoot. Sadly, it's time to drive it away from the camp grounds.\"",
  "locale:429076 [npc_dialog | - | Robbie] \"<font size='20'>Don't call me Bob!</font><BR>Oh, that little treeble... I'm going to come up with a new way to get at him, I swear!<BR><BR>Well, now that you're\"",
  "locale:429078 [quest_objective | - | Confronting Bigfoot] 'Confront Bigfoot and see what he wants.'",
  "locale:429083 [quest_dialog | - | Chatty] \"I can't believe those robgoblins would pull such a prank! Please let camp master Chatty know what we discovered and that the problem's been taken care of.\"",
  "locale:429087 [quest_dialog | - | Talk to Bob] 'Haha! Bob was behind the Bigfoot scare? I gotta admit, that was pretty clever. <BR><BR>Head to the other camp and give Bob my regards, will ya?'",
  "locale:429089 [quest_objective | - | Talk to Bob] 'Talk to Bob'",
  "locale:429091 [quest_objective | - | Robbie] \"We should let camp leader Chatty know that Bigfoot's another one of Bob--err, Robbie's pranks. \""
 ],
